import itertools

def solve():
    def get_l_trominos(n):
        trominos = []
        for r in range(n - 1):
            for c in range(n - 1):
                # 2x2 square starting at r, c
                # L-tromino is 2x2 minus one square
                for i in range(2):
                    for j in range(2):
                        # remove square (r+i, c+j)
                        tromino = []
                        for ri in range(2):
                            for cj in range(2):
                                if ri != i or cj != j:
                                    tromino.append((r + ri, c + cj))
                        trominos.append(tuple(sorted(tromino)))
        return trominos

    def is_black(r, c):
        return (r + c) % 2 == 0

    def check(n):
        black_squares = set((r, c) for r in range(n) for c in range(n) if is_black(r, c))
        all_trominos = get_l_trominos(n)

        # We want to cover all black_squares with non-overlapping trominos.
        # This is a search problem.
        # n_trominos can range from ceil(len(black_squares)/2) up to floor(n*n/3).

        min_n = (len(black_squares) + 1) // 2
        max_n = (n * n) // 3

        for num_t in range(min_n, max_n + 1):
            # Search for a combination of num_t non-overlapping trominos that cover all black squares.
            # To optimize, we can use backtracking.

            def backtrack(current_covered, tromino_idx, count):
                if count == num_t:
                    if black_squares.issubset(current_covered):
                        return True
                    return False

                # To avoid redundant searches, we only consider trominos after tromino_idx
                for i in range(tromino_idx, len(all_trominos)):
                    t = all_trominos[i]
                    if any(sq in current_covered for sq in t):
                        continue
                    if backtrack(current_covered | set(t), i + 1, count + 1):
                        return True
                return False

            if backtrack(set(), 0, 0):
                return num_t
        return None

    print(f"3x3: {check(3)}")
    print(f"5x5: {check(5)}")

