                        trominos.append(tuple(sorted(tromino)))
        return trominos

    def is_black(r, c):
        return (r + c) % 2 == 0

    black_squares = sorted([ (r, c) for r in range(n) for c in range(n) if is_black(r, c) ], reverse=True)
    all_trominos = get_l_trominos(n)

    # Precompute which trominos cover each black square
    black_to_trominos = {sq: [] for sq in black_squares}
    for t in all_trominos:
        for sq in t:
            if sq in black_to_trominos:
                black_to_trominos[sq].append(t)

    def backtrack(uncovered_black, current_covered, count, max_count):
        if not uncovered_black:
            return True
        if count >= max_count:
            return False

        # Pick a black square to cover
        sq = uncovered_black[0]

        # Try all trominos that cover this square
        for t in black_to_trominos[sq]:
            # Check if tromino t overlaps with current_covered
            if any(s in current_covered for s in t):
                continue

            # New uncovered black squares
            new_uncovered = [s for s in uncovered_black if s not in t]

            if backtrack(new_uncovered, current_covered | set(t), count + 1, max_count):
                return True
        return False

    # Try different values for max_count
    min_n = (len(black_squares) + 1) // 2
    max_n = (n * n) // 3
    for max_count in range(min_n, max_n + 1):
        if backtrack(black_squares, set(), 0, max_count):
            return max_count
    return None

